def gcd_brute(a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    for x in range(min(a, b), 0, -1):
        if a % x == 0 and b % x == 0:
            return x
    return a or b

def gcd(a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def lcm(a: int, b: int) -> int:
    return abs(a // gcd(a, b) * b)  # divide before multiply
